template:
PREFIX aegis: <http://aegis.gastown.local/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT DISTINCT ?node ?mode WHERE {
  VALUES ?key { '{repo}' }
  ?node a aegis:GitRepo ; aegis:reviewMode ?mode .
  { ?node rdfs:label ?term } UNION { ?node skos:altLabel ?term }
  FILTER(STR(?term) = ?key)
}
ORDER BY ?node ?mode
LIMIT 64
